// Auto-counting for categories
alphabetCategories.forEach((cat) => {
  cat.count = medicines.filter(
    (m) => cat.id === "all" || m.firstLetter === cat.letter,
  ).length;
});

familyCategories.forEach((cat) => {
  cat.count = medicines.filter(
    (m) => cat.id === "all" || m.categoryId === cat.id,
  ).length;
});
